scripts.script:
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
    Name = "Shaders Hub",
    LoadingTitle = "Loading Interface...",
    LoadingSubtitle = "loading script",
    Theme = "Ocean",
    ConfigurationSaving = {
        Enabled = true,
        FolderName = nil,
        FileName = "Hub"
    },
    Discord = {
        Enabled = false,
        Invite = "noinvitelink",
        RememberJoins = false
    },
    KeySystem = false
})

local MainPage = Window:CreateTab("Main", "home")

MainPage:CreateParagraph({
    Title = "Information",
    Content = "¡SCRIPT MADE BY GEMINI SORRY!\n\nthis script uses some shaders who not made by me, i will give credits to that creator.\nthanks for read."
})

local ShadersPage = Window:CreateTab("Shaders", "image")

ShadersPage:CreateButton({
    Name = "shaders 4k (NOT MINE)",
    Callback = function()
        loadstring(game:HttpGet('https://raw.githubusercontent.com/randomstring0/pshade-ultimate/refs/heads/main/src/cd.lua'))()
    end
})

local MorePage = Window:CreateTab("More", "plus")

MorePage:CreateLabel("soon")
